import{_ as r,a0 as d,w as f,s,I as n,x as e,a1 as o,A as i,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"用 nftwatch 監控你的 Linux 防火牆 | LCTT x X-CMD","titleTemplate":false,"description":"用 nftwatch 監控你的 Linux 防火牆 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 nftwatch 監控你的 Linux 防火牆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 nftwatch 監控你的 Linux 防火牆 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220718 Monitor your Linux firewall with nftwatch","title":"用 nftwatch 監控你的 Linux 防火牆","tag":"202207","desc":""},"relativePath":"202207/20220718 Monitor your Linux firewall with nftwatch.md","filePath":"[post].md"}'),p={name:"202207/20220718 Monitor your Linux firewall with nftwatch.md"};function u(w,t,h,m,x,T){const l=d("Link");return f(),s("div",null,[t[24]||(t[24]=n("h1",{id:"用-nftwatch-監控你的-linux-防火牆",tabindex:"-1"},[e("用 nftwatch 監控你的 Linux 防火牆 "),n("a",{class:"header-anchor",href:"#用-nftwatch-監控你的-linux-防火牆","aria-label":"Permalink to “用 nftwatch 監控你的 Linux 防火牆”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/24/070724d542rvbbg3af3o9p.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"我創建了 Linux nftwatch 命令來觀察防火牆的流量統計。")],-1)),n("p",null,[t[1]||(t[1]=e("Netfilter 表（",-1)),o(l,{href:"https://developers.redhat.com/blog/2016/10/28/what-comes-after-iptables-its-successor-of-course-nftables?extIdCarryOver=true&sc_cid=701f2000001OH79AAG#getting_started"},{default:i(()=>[...t[0]||(t[0]=[e("nftables",-1)])]),_:1}),t[2]||(t[2]=e("）是現代 Linux 發行版中的默認防火牆。它在 Fedora 和 RHEL 8、最新的 Debian 和許多其他版本上都有。它取代了早期發行版中捆綁的舊版 iptables。它是一個強大的、值得的 iptables 替代品，作為一個廣泛使用它的人，我欣賞它的能力和功能。",-1))]),t[27]||(t[27]=a('<p>nftables 的一個特點是能夠為許多元素添加計數器，例如規則。這些都是按需啓用的。你需要使用 <code>counter</code> 參數，在每一行明確地要求它。我為我的防火牆中的特定規則啓用了這些計數器，這使我能夠看到這些規則。</p><p>這讓我開始思考。我怎樣才能實時查看這些計數器？一開始我嘗試了 <code>watch</code>，它允許諸如刷新率之類的東西，但我不喜歡默認格式，而且它不能滾動。我發現使用 <code>head</code> 和 <code>tail</code> 以及 <code>awk</code> 也不理想，並不存在一個用户友好的解決方案。所以我自己寫了一個，我想與開源社區分享。</p><h3 id="linux-上的-nftwatch-介紹" tabindex="-1">Linux 上的 nftwatch 介紹 <a class="header-anchor" href="#linux-上的-nftwatch-介紹" aria-label="Permalink to “Linux 上的 nftwatch 介紹”">​</a></h3><p>我的解決方案，我稱之為 <code>nftwatch</code>，做了幾件事：</p><ul><li>它對 nftables 的輸出進行重新排序和改寫，使其更具有可讀性。</li><li>它允許向上或向下滾動輸出。</li><li>可以由用户定義的刷新率（可以實時改變）。</li><li>它可以暫停顯示。</li></ul><p>你得到的不是一個表格的轉儲，而是顯示每個規則活動的輸出。</p><p><img src="https://opensource.com/sites/default/files/2022-07/nftwatch-sample.png" alt="Image of nftwatch"></p>',7)),n("p",null,[t[4]||(t[4]=e("你可以從它的 ",-1)),o(l,{href:"https://github.com/flyingrhinonz/nftwatch"},{default:i(()=>[...t[3]||(t[3]=[e("Git 倉庫",-1)])]),_:1}),t[5]||(t[5]=e("下載它。",-1))]),t[28]||(t[28]=a('<p>它是 100% 的 Python 代碼，100% 的開源，100% 的免費。它滿足了所有免費的高質量程序的要求。</p><h3 id="在-linux-上安裝-nftwatch" tabindex="-1">在 Linux 上安裝 nftwatch <a class="header-anchor" href="#在-linux-上安裝-nftwatch" aria-label="Permalink to “在 Linux 上安裝 nftwatch”">​</a></h3><p>以下是手動安裝説明：</p><ol><li>克隆或從 git 倉庫下載該項目。</li><li>將 <code>nftwatch.yml</code> 複製到 <code>/etc/nftwatch.yml</code>。</li><li>將 <code>nftwatch</code> 複製到 <code>/usr/local/bin/nftwatch</code> 並使用 <code>chmod a+x</code> 授予其可執行權限。</li><li>使用 <code>nftwatch</code>，不帶任何參數來運行它。</li><li>參見 <code>nftwatch -m</code> 的手冊。</li></ol>',4)),n("p",null,[t[7]||(t[7]=e("你也可以在沒有 ",-1)),o(l,{href:"https://opensource.com/article/21/9/yaml-cheat-sheet"},{default:i(()=>[...t[6]||(t[6]=[e("YAML",-1)])]),_:1}),t[8]||(t[8]=e(" 配置文件的情況下運行 nftwatch，在這種情況下它使用內置的默認值。",-1))]),t[29]||(t[29]=a('<h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p><code>nftwatch</code> 命令顯示 nftables 規則。大多數控制都是為此目的而設計的。</p><p>箭頭鍵和等效的 Vim 的按鍵控制滾動。使用 <code>F</code> 或 <code>S</code> 鍵來改變刷新速度。使用 <code>P</code> 鍵來暫停顯示。</p><p>運行 <code>nftwatch -m</code> 以獲得完整的説明，以及交互式按鍵控制的列表。</p><h3 id="防火牆的新觀點" tabindex="-1">防火牆的新觀點 <a class="header-anchor" href="#防火牆的新觀點" aria-label="Permalink to “防火牆的新觀點”">​</a></h3><p>即使你花費了時間去配置防火牆，它也會顯得晦澀難懂和模糊不清。除了從日誌條目中推斷指標外，很難判斷你的防火牆實際看到的活動類型。 使用 <code>nftwatch</code>，你可以看到你的防火牆在工作，並且可以更好地瞭解你的網絡每天需要處理的流量類型。</p><p><em>（文內圖片來自 Kenneth Aaron，CC BY-SA 4.0）</em></p><hr>',8)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),o(l,{href:"https://opensource.com/article/22/7/nftwatch-linux-firewall"},{default:i(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/22/7/nftwatch-linux-firewall",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),o(l,{href:"https://opensource.com/users/flyingrhino"},{default:i(()=>[...t[11]||(t[11]=[e("Kenneth Aaron",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),o(l,{href:"https://github.com/lkxed"},{default:i(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),o(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[13]||(t[13]=[e("geekpi",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const g=r(p,[["render",u]]);export{L as __pageData,g as default};
